window.PbinClojureDocs = {"clojure.core":{"+":["([] [x] [x y] [x y & more])","Returns the sum of nums. (+) returns 0.","fn"],"->":["([x & forms])","Threads the expr through the forms. Inserts x as the\n  second item in the first form, making a list of it if it is not a\n  list already. If there are more forms, inserts the first form as the\n  second item in second form, etc.","macro"],"->>":["([x & forms])","Threads the expr through the forms. Inserts x as the\n  last item in the first form, making a list of it if it is not a\n  list already. If there are more forms, inserts the first form as the\n  last item in second form, etc.","macro"],"..":["([x form] [x form & more])","form => fieldName-symbol or (instanceMethodName-symbol args*)\n\n  Expands into a member access (.) of the first member on the first\n  argument, followed by the next member on the result, etc. For\n  instance:\n\n  (.. System (getProperties) (get \"os.name\"))\n\n  expands to:\n\n  (. (. System (getProperties)) (get \"os.name\"))\n\n  but is easier to write, read, and understand.","macro"],"/":["([x] [x y] [x y & more])","If no denominators are supplied, returns 1/numerator,\n  else returns numerator divided by all of the denominators.","fn"],"<":["([x] [x y] [x y & more])","Returns non-nil if nums are in monotonically increasing order,\n  otherwise false.","fn"],"<=":["([x] [x y] [x y & more])","Returns non-nil if nums are in monotonically non-decreasing order,\n  otherwise false.","fn"],"=":["([x] [x y] [x y & more])","Equality. Returns true if x equals y, false if not. Compares\n  numbers and collections in a type-independent manner.  Clojure's immutable data\n  structures define -equiv (and thus =) as a value, not an identity,\n  comparison.","fn"],"==":["([x] [x y] [x y & more])","Returns non-nil if nums all have the equivalent\n  value, otherwise false. Behavior on non nums is\n  undefined.","fn"],">":["([x] [x y] [x y & more])","Returns non-nil if nums are in monotonically decreasing order,\n  otherwise false.","fn"],">=":["([x] [x y] [x y & more])","Returns non-nil if nums are in monotonically non-increasing order,\n  otherwise false.","fn"],"NaN?":["([val])","Returns true if num is NaN, else false","fn"],"abs":["([a])","Returns the absolute value of a.","fn"],"aclone":["([arr])","Returns a javascript array, cloned from the passed in array","fn"],"add-watch":["([iref key f])","Adds a watch function to an atom reference. The watch fn must be a\n  fn of 4 args: a key, the reference, its old-state, its\n  new-state. Whenever the reference's state might have been changed,\n  any registered watches will have their functions called. The watch\n  fn will be called synchronously. Note that an atom's state\n  may have changed again prior to the fn call, so use old/new-state\n  rather than derefing the reference. Keys must be unique per\n  reference, and can be used to remove the watch with remove-watch,\n  but are otherwise considered opaque by the watch mechanism.  Bear in\n  mind that regardless of the result or action of the watch fns the\n  atom's value will change.  Example:\n\n      (def a (atom 0))\n      (add-watch a :inc (fn [k r o n] (assert (== 0 n))))\n      (swap! a inc)\n      ;; Assertion Error\n      (deref a)\n      ;=> 1","fn"],"aget":["([array idx] [array idx & idxs])","Returns the value at the index/indices. Works on JavaScript arrays.","fn"],"alength":["([array])","Returns the length of the array. Works on arrays of all types.","fn"],"alter-meta!":["([iref f & args])","Atomically sets the metadata for a namespace/var/ref/agent/atom to be:\n\n  (apply f its-current-meta args)\n\n  f must be free of side-effects","fn"],"amap":["([a idx ret expr])","Maps an expression across an array a, using an index named idx, and\n  return value named ret, initialized to a clone of a, then setting\n  each element of ret to the evaluation of expr, returning the new\n  array ret.","macro"],"ancestors":["([tag] [h tag])","Returns the immediate and indirect parents of tag, either via a JavaScript type\n  inheritance relationship or a relationship established via derive. h\n  must be a hierarchy obtained from make-hierarchy, if not supplied\n  defaults to the global hierarchy","fn"],"and":["([] [x] [x & next])","Evaluates exprs one at a time, from left to right. If a form\n  returns logical false (nil or false), and returns that value and\n  doesn't evaluate any of the other expressions, otherwise it returns\n  the value of the last expr. (and) returns true.","macro"],"any?":["([x])","Returns true if given any argument.","fn"],"apply":["([f args] [f x args] [f x y args] [f x y z args] [f a b c d & args])","Applies fn f to the argument list formed by prepending intervening arguments to args.","fn"],"areduce":["([a idx ret init expr])","Reduces an expression across an array a, using an index named idx,\n  and return value named ret, initialized to init, setting ret to the\n  evaluation of expr at each step, returning ret.","macro"],"array":["([var-args])","Creates a new javascript array.\n@param {...*} var_args","fn"],"array-map":["([& keyvals])","keyval => key val\n  Returns a new array map with supplied mappings.","fn"],"array?":["([x])","Returns true if x is a JavaScript array.","fn"],"as->":["([expr name & forms])","Binds name to expr, evaluates the first form in the lexical context\n  of that binding, then binds name to that result, repeating for each\n  successive form, returning the result of the last form.","macro"],"aset":["([array idx val] [array idx idx2 & idxv])","Sets the value at the index/indices. Works on JavaScript arrays.\n  Returns val.","fn"],"assert":["([x] [x message])","Evaluates expr and throws an exception if it does not evaluate to\n  logical true.","macro"],"assoc":["([coll k v] [coll k v & kvs])","assoc[iate]. When applied to a map, returns a new map of the\n   same (hashed/sorted) type, that contains the mapping of key(s) to\n   val(s). When applied to a vector, returns a new vector that\n   contains val at index. Note - index must be <= (count vector).","fn"],"assoc!":["([tcoll key val] [tcoll key val & kvs])","When applied to a transient map, adds mapping of key(s) to\n  val(s). When applied to a transient vector, sets the val at index.\n  Note - index must be <= (count vector). Returns coll.","fn"],"assoc-in":["([m [k & ks] v])","Associates a value in a nested associative structure, where ks is a\n  sequence of keys and v is the new value and returns a new nested structure.\n  If any levels do not exist, hash-maps will be created.","fn"],"associative?":["([x])","Returns true if coll implements IAssociative","fn"],"atom":["([x] [x & {:keys [meta validator]}])","Creates and returns an Atom with an initial value of x and zero or\n  more options (in any order):\n\n  :meta metadata-map\n\n  :validator validate-fn\n\n  If metadata-map is supplied, it will become the metadata on the\n  atom. validate-fn must be nil or a side-effect-free fn of one\n  argument, which will be passed the intended new state on any state\n  change. If the new state is unacceptable, the validate-fn should\n  return false or throw an Error.  If either of these error conditions\n  occur, then the value of the atom will not change.","fn"],"binding":["([bindings & body])","binding => var-symbol init-expr\n\n  Creates new bindings for the (already-existing) vars, with the\n  supplied initial values, executes the exprs in an implicit do, then\n  re-establishes the bindings that existed before.  The new bindings\n  are made in parallel (unlike let); all init-exprs are evaluated\n  before the vars are bound to their new values.","macro"],"bit-and":["([x y] [x y & more])","Bitwise and","fn"],"bit-and-not":["([x y] [x y & more])","Bitwise and with complement","fn"],"bit-flip":["([x n])","Flip bit at index n","fn"],"bit-not":["([x])","Bitwise complement","fn"],"bit-or":["([x y] [x y & more])","Bitwise or","fn"],"bit-set":["([x n])","Set bit at index n","fn"],"bit-shift-left":["([x n])","Bitwise shift left","fn"],"bit-shift-right":["([x n])","Bitwise shift right","fn"],"bit-test":["([x n])","Test bit at index n","fn"],"bit-xor":["([x y] [x y & more])","Bitwise exclusive or","fn"],"boolean":["([x])","Coerce to boolean","fn"],"boolean?":["([x])","Return true if x is a Boolean","fn"],"booleans":["([x])",null,"fn"],"bounded-count":["([n coll])","If coll is counted? returns its count, else will count at most the first n\n   elements of coll using its seq","fn"],"butlast":["([s])","Return a seq of all but the last item in coll, in linear time","fn"],"byte":["([x])",null,"fn"],"bytes":["([x])",null,"fn"],"case":["([e & clauses])","Takes an expression, and a set of clauses.\n\n  Each clause can take the form of either:\n\n  test-constant result-expr\n\n  (test-constant1 ... test-constantN)  result-expr\n\n  The test-constants are not evaluated. They must be compile-time\n  literals, and need not be quoted.  If the expression is equal to a\n  test-constant, the corresponding result-expr is returned. A single\n  default expression can follow the clauses, and its value will be\n  returned if no clause matches. If no default expression is provided\n  and no clause matches, an Error is thrown.\n\n  Unlike cond and condp, case does a constant-time dispatch, the\n  clauses are not considered sequentially.  All manner of constant\n  expressions are acceptable in case, including numbers, strings,\n  symbols, keywords, and (ClojureScript) composites thereof. Note that since\n  lists are used to group multiple constants that map to the same\n  expression, a vector can be used to match a list if needed. The\n  test-constants need not be all of the same type.","macro"],"cat":["([rf])","A transducer which concatenates the contents of each input, which must be a\n  collection, into the reduction.","fn"],"char":["([x])","Coerce to char","fn"],"char?":["([x])","Returns true if x is a JavaScript string of length one.","fn"],"chars":["([x])",null,"fn"],"chunk":["([b])",null,"fn"],"chunk-append":["([b x])",null,"fn"],"chunk-buffer":["([capacity])",null,"fn"],"chunk-cons":["([chunk rest])",null,"fn"],"chunk-first":["([s])",null,"fn"],"chunk-next":["([s])",null,"fn"],"chunk-rest":["([s])",null,"fn"],"chunked-seq?":["([x])","Return true if x satisfies IChunkedSeq.","fn"],"clj->js":["([x & {:keys [keyword-fn] :or {keyword-fn name} :as options}])","Recursively transforms ClojureScript values to JavaScript.\n  sets/vectors/lists become Arrays, Keywords and Symbol become Strings,\n  Maps become Objects. Arbitrary keys are encoded to by `key->js`.\n  Options is a key-value pair, where the only valid key is\n  :keyword-fn, which should point to a single-argument function to be\n  called on keyword keys. Default to `name`.","fn"],"coll?":["([x])","Returns true if x satisfies ICollection","fn"],"comment":["([& body])","Ignores body, yields nil","macro"],"comp":["([] [f] [f g] [f g h] [f1 f2 f3 & fs])","Takes a set of functions and returns a fn that is the composition\n  of those fns.  The returned fn takes a variable number of args,\n  applies the rightmost of fns to the args, the next\n  fn (right-to-left) to the result, etc.","fn"],"comparator":["([pred])","Returns an JavaScript compatible comparator based upon pred.","fn"],"compare":["([x y])","Comparator. Returns a negative number, zero, or a positive number\n  when x is logically 'less than', 'equal to', or 'greater than'\n  y. Uses IComparable if available and google.array.defaultCompare for objects\n of the same type and special-cases nil to be less than any other object.","fn"],"compare-and-set!":["([^ not-native a oldval newval])","Atomically sets the value of atom to newval if and only if the\n  current value of the atom is equal to oldval. Returns true if\n  set happened, else false.","fn"],"complement":["([f])","Takes a fn f and returns a fn that takes the same arguments as f,\n  has the same effects, if any, and returns the opposite truth value.","fn"],"completing":["([f] [f cf])","Takes a reducing function f of 2 args and returns a fn suitable for\n  transduce by adding an arity-1 signature that calls cf (default -\n  identity) on the result argument.","fn"],"concat":["([] [x] [x y] [x y & zs])","Returns a lazy seq representing the concatenation of the elements in the supplied colls.","fn"],"cond":["([& clauses])","Takes a set of test/expr pairs. It evaluates each test one at a\n  time.  If a test returns logical true, cond evaluates and returns\n  the value of the corresponding expr and doesn't evaluate any of the\n  other tests or exprs. (cond) returns nil.","macro"],"cond->":["([expr & clauses])","Takes an expression and a set of test/form pairs. Threads expr (via ->)\n  through each form for which the corresponding test\n  expression is true. Note that, unlike cond branching, cond-> threading does\n  not short circuit after the first true test expression.","macro"],"cond->>":["([expr & clauses])","Takes an expression and a set of test/form pairs. Threads expr (via ->>)\n  through each form for which the corresponding test expression\n  is true.  Note that, unlike cond branching, cond->> threading does not short circuit\n  after the first true test expression.","macro"],"condp":["([pred expr & clauses])","Takes a binary predicate, an expression, and a set of clauses.\n  Each clause can take the form of either:\n\n  test-expr result-expr\n\n  test-expr :>> result-fn\n\n  Note :>> is an ordinary keyword.\n\n  For each clause, (pred test-expr expr) is evaluated. If it returns\n  logical true, the clause is a match. If a binary clause matches, the\n  result-expr is returned, if a ternary clause matches, its result-fn,\n  which must be a unary function, is called with the result of the\n  predicate as its argument, the result of that call being the return\n  value of condp. A single default expression can follow the clauses,\n  and its value will be returned if no clause matches. If no default\n  expression is provided and no clause matches, an Error is thrown.","macro"],"conj":["([] [coll] [coll x] [coll x & xs])","conj[oin]. Returns a new collection with the xs\n  'added'. (conj nil item) returns (item).\n  (conj coll) returns coll. (conj) returns [].\n  The 'addition' may happen at different 'places' depending\n  on the concrete type.","fn"],"conj!":["([] [tcoll] [tcoll val] [tcoll val & vals])","Adds val to the transient collection, and return tcoll. The 'addition'\n  may happen at different 'places' depending on the concrete type.","fn"],"cons":["([x coll])","Returns a new seq where x is the first element and coll is the rest.","fn"],"constantly":["([x])","Returns a function that takes any number of arguments and returns x.","fn"],"contains?":["([coll v])","Returns true if key is present in the given collection, otherwise\n  returns false.  Note that for numerically indexed collections like\n  vectors and arrays, this tests if the numeric key is within the\n  range of indexes. 'contains?' operates constant or logarithmic time;\n  it will not perform a linear search for a value.  See also 'some'.","fn"],"count":["([coll])","Returns the number of items in the collection. (count nil) returns\n  0.  Also works on strings, arrays, and Maps","fn"],"counted?":["([x])","Returns true if coll implements count in constant time","fn"],"create-ns":["([sym] [sym ns-obj])","Create a new namespace named by the symbol. Bootstrap only.","fn"],"cycle":["([coll])","Returns a lazy (infinite!) sequence of repetitions of the items in coll.","fn"],"dec":["([x])","Returns a number one less than num.","fn"],"declare":["([& names])","defs the supplied var names with no bindings, useful for making forward declarations.","macro"],"dedupe":["([] [coll])","Returns a lazy sequence removing consecutive duplicates in coll.\n  Returns a transducer when no collection is provided.","fn"],"defmacro":["([name doc-string? attr-map? [params*] body] [name doc-string? attr-map? ([params*] body) + attr-map?])","Like defn, but the resulting function name is declared as a\n  macro and will be used as a macro by the compiler when it is\n  called.","macro"],"defmethod":["([multifn dispatch-val & fn-tail])","Creates and installs a new method of multimethod associated with dispatch-value. ","macro"],"defmulti":["([name docstring? attr-map? dispatch-fn & options])","Creates a new multimethod with the associated dispatch function.\n  The docstring and attribute-map are optional.\n\n  Options are key-value pairs and may be one of:\n    :default    the default dispatch value, defaults to :default\n    :hierarchy  the isa? hierarchy to use for dispatching\n                defaults to the global hierarchy","macro"],"defn":["([name doc-string? attr-map? [params*] prepost-map? body] [name doc-string? attr-map? ([params*] prepost-map? body) + attr-map?])","Same as (def name (core/fn [params* ] exprs*)) or (def\n    name (core/fn ([params* ] exprs*)+)) with any doc-string or attrs added\n    to the var metadata. prepost-map defines a map with optional keys\n    :pre and :post that contain collections of pre or post conditions.","macro"],"defn-":["([name & decls])","same as defn, yielding non-public def","macro"],"defonce":["([x init])","defs name to have the root value of init iff the named var has no root value,\n  else init is unevaluated","macro"],"defprotocol":["([psym & doc+methods])","A protocol is a named set of named methods and their signatures:\n\n  (defprotocol AProtocolName\n    ;optional doc string\n    \"A doc string for AProtocol abstraction\"\n\n  ;method signatures\n    (bar [this a b] \"bar docs\")\n    (baz [this a] [this a b] [this a b c] \"baz docs\"))\n\n  No implementations are provided. Docs can be specified for the\n  protocol overall and for each method. The above yields a set of\n  polymorphic functions and a protocol object. All are\n  namespace-qualified by the ns enclosing the definition The resulting\n  functions dispatch on the type of their first argument, which is\n  required and corresponds to the implicit target object ('this' in\n  JavaScript parlance). defprotocol is dynamic, has no special compile-time\n  effect, and defines no new types.\n\n  (defprotocol P\n    (foo [this])\n    (bar-me [this] [this y]))\n\n  (deftype Foo [a b c]\n    P\n    (foo [this] a)\n    (bar-me [this] b)\n    (bar-me [this y] (+ c y)))\n\n  (bar-me (Foo. 1 2 3) 42)\n  => 45\n\n  (foo\n    (let [x 42]\n      (reify P\n        (foo [this] 17)\n        (bar-me [this] x)\n        (bar-me [this y] x))))\n  => 17","macro"],"defrecord":["([rsym fields & impls])","(defrecord name [fields*]  options* specs*)\n\n  Currently there are no options.\n\n  Each spec consists of a protocol or interface name followed by zero\n  or more method bodies:\n\n  protocol-or-Object\n  (methodName [args*] body)*\n\n  The record will have the (immutable) fields named by\n  fields, which can have type hints. Protocols and methods\n  are optional. The only methods that can be supplied are those\n  declared in the protocols.  Note that method bodies are\n  not closures, the local environment includes only the named fields,\n  and those fields can be accessed directly.\n\n  Method definitions take the form:\n\n  (methodname [args*] body)\n\n  The argument and return types can be hinted on the arg and\n  methodname symbols. If not supplied, they will be inferred, so type\n  hints should be reserved for disambiguation.\n\n  Methods should be supplied for all methods of the desired\n  protocol(s). You can also define overrides for\n  methods of Object. Note that a parameter must be supplied to\n  correspond to the target object ('this' in JavaScript parlance). Note also\n  that recur calls to the method head should *not* pass the target object, it\n  will be supplied automatically and can not be substituted.\n\n  In the method bodies, the (unqualified) name can be used to name the\n  class (for calls to new, instance? etc).\n\n  The type will have implementations of several ClojureScript\n  protocol generated automatically: IMeta/IWithMeta (metadata support) and\n  IMap, etc.\n\n  In addition, defrecord will define type-and-value-based =,\n  and will define ClojureScript IHash and IEquiv.\n\n  Two constructors will be defined, one taking the designated fields\n  followed by a metadata map (nil for none) and an extension field\n  map (nil for none), and one taking only the fields (using nil for\n  meta and extension fields). Note that the field names __meta\n  and __extmap are currently reserved and should not be used when\n  defining your own records.\n\n  Given (defrecord TypeName ...), two factory functions will be\n  defined: ->TypeName, taking positional parameters for the fields,\n  and map->TypeName, taking a map of keywords to field values.","macro"],"deftype":["([t fields & impls])","(deftype name [fields*]  options* specs*)\n\n  Currently there are no options.\n\n  Each spec consists of a protocol or interface name followed by zero\n  or more method bodies:\n\n  protocol-or-Object\n  (methodName [args*] body)*\n\n  The type will have the (by default, immutable) fields named by\n  fields, which can have type hints. Protocols and methods\n  are optional. The only methods that can be supplied are those\n  declared in the protocols/interfaces.  Note that method bodies are\n  not closures, the local environment includes only the named fields,\n  and those fields can be accessed directly. Fields can be qualified\n  with the metadata :mutable true at which point (set! afield aval) will be\n  supported in method bodies. Note well that mutable fields are extremely\n  difficult to use correctly, and are present only to facilitate the building\n  of higherlevel constructs, such as ClojureScript's reference types, in\n  ClojureScript itself. They are for experts only - if the semantics and\n  implications of :mutable are not immediately apparent to you, you should not\n  be using them.\n\n  Method definitions take the form:\n\n  (methodname [args*] body)\n\n  The argument and return types can be hinted on the arg and\n  methodname symbols. If not supplied, they will be inferred, so type\n  hints should be reserved for disambiguation.\n\n  Methods should be supplied for all methods of the desired\n  protocol(s). You can also define overrides for methods of Object. Note that\n  a parameter must be supplied to correspond to the target object\n  ('this' in JavaScript parlance). Note also that recur calls to the method\n  head should *not* pass the target object, it will be supplied\n  automatically and can not be substituted.\n\n  In the method bodies, the (unqualified) name can be used to name the\n  class (for calls to new, instance? etc).\n\n  One constructor will be defined, taking the designated fields.  Note\n  that the field names __meta and __extmap are currently reserved and\n  should not be used when defining your own types.\n\n  Given (deftype TypeName ...), a factory function called ->TypeName\n  will be defined, taking positional parameters for the fields","macro"],"delay":["([& body])","Takes a body of expressions and yields a Delay object that will\n  invoke the body only the first time it is forced (with force or deref/@), and\n  will cache the result and return it on all subsequent force\n  calls.","macro"],"delay?":["([x])","returns true if x is a Delay created with delay","fn"],"demunge":["([name])",null,"fn"],"deref":["([o])","Also reader macro: @var/@atom/@delay. Returns the\n   most-recently-committed value of ref. When applied to a var\n   or atom, returns its current state. When applied to a delay, forces\n   it if not already forced. See also - realized?.","fn"],"derive":["([tag parent] [h tag parent])","Establishes a parent/child relationship between parent and\n  tag. Parent must be a namespace-qualified symbol or keyword and\n  child can be either a namespace-qualified symbol or keyword or a\n  class. h must be a hierarchy obtained from make-hierarchy, if not\n  supplied defaults to, and modifies, the global hierarchy.","fn"],"descendants":["([tag] [h tag])","Returns the immediate and indirect children of tag, through a\n  relationship established via derive. h must be a hierarchy obtained\n  from make-hierarchy, if not supplied defaults to the global\n  hierarchy. Note: does not work on JavaScript type inheritance\n  relationships.","fn"],"disj":["([coll] [coll k] [coll k & ks])","disj[oin]. Returns a new set of the same (hashed/sorted) type, that\n  does not contain key(s).","fn"],"disj!":["([tcoll val] [tcoll val & vals])","disj[oin]. Returns a transient set of the same (hashed/sorted) type, that\n  does not contain key(s).","fn"],"dissoc":["([coll] [coll k] [coll k & ks])","dissoc[iate]. Returns a new map of the same (hashed/sorted) type,\n  that does not contain a mapping for key(s).","fn"],"dissoc!":["([tcoll key] [tcoll key & ks])","Returns a transient map that doesn't contain a mapping for key(s).","fn"],"distinct":["([] [coll])","Returns a lazy sequence of the elements of coll with duplicates removed.\n  Returns a stateful transducer when no collection is provided.","fn"],"distinct?":["([x] [x y] [x y & more])","Returns true if no two of the arguments are =","fn"],"doall":["([coll] [n coll])","When lazy sequences are produced via functions that have side\n  effects, any effects other than those needed to produce the first\n  element in the seq do not occur until the seq is consumed. doall can\n  be used to force any effects. Walks through the successive nexts of\n  the seq, retains the head and returns it, thus causing the entire\n  seq to reside in memory at one time.","fn"],"dorun":["([coll] [n coll])","When lazy sequences are produced via functions that have side\n  effects, any effects other than those needed to produce the first\n  element in the seq do not occur until the seq is consumed. dorun can\n  be used to force any effects. Walks through the successive nexts of\n  the seq, does not retain the head and returns nil.","fn"],"doseq":["([seq-exprs & body])","Repeatedly executes body (presumably for side-effects) with\n  bindings and filtering as provided by \"for\".  Does not retain\n  the head of the sequence. Returns nil.","macro"],"dotimes":["([bindings & body])","bindings => name n\n\n  Repeatedly executes body (presumably for side-effects) with name\n  bound to integers from 0 through n-1.","macro"],"doto":["([x & forms])","Evaluates x then calls all of the methods and functions with the\n  value of x supplied at the front of the given arguments.  The forms\n  are evaluated in order.  Returns x.\n\n  (doto (new js/Map) (.set \"a\" 1) (.set \"b\" 2))","macro"],"double":["([x])",null,"fn"],"double-array":["([size-or-seq] [size init-val-or-seq])","Creates an array of doubles. Does not coerce array, provided for compatibility\n  with Clojure.","fn"],"double?":["([x])","Returns true for JavaScript numbers, false otherwise.","fn"],"doubles":["([x])",null,"fn"],"drop":["([n] [n coll])","Returns a laziness-preserving sequence of all but the first n items in coll.\n  Returns a stateful transducer when no collection is provided.","fn"],"drop-last":["([s] [n s])","Return a lazy sequence of all but the last n (default 1) items in coll","fn"],"drop-while":["([pred] [pred coll])","Returns a lazy sequence of the items in coll starting from the\n  first item for which (pred item) returns logical false.  Returns a\n  stateful transducer when no collection is provided.","fn"],"eduction":["([& xforms])","Returns a reducible/iterable application of the transducers\n  to the items in coll. Transducers are applied in order as if\n  combined with comp. Note that these applications will be\n  performed every time reduce/iterator is called.","fn"],"empty":["([coll])","Returns an empty collection of the same category as coll, or nil","fn"],"empty?":["([coll])","Returns true if coll has no items. To check the emptiness of a seq,\n  please use the idiom (seq x) rather than (not (empty? x))","fn"],"ensure-reduced":["([x])","If x is already reduced?, returns it, else returns (reduced x)","fn"],"eval":["([form])","Evaluates the form data structure (not text!) and returns the result.\n  Delegates to cljs.core/*eval*. Intended for use in self-hosted ClojureScript,\n  which sets up an implementation of cljs.core/*eval* for that environment.","fn"],"even?":["([n])","Returns true if n is even, throws an exception if n is not an integer","fn"],"every-pred":["([p] [p1 p2] [p1 p2 p3] [p1 p2 p3 & ps])","Takes a set of predicates and returns a function f that returns true if all of its\n  composing predicates return a logical true value against all of its arguments, else it returns\n  false. Note that f is short-circuiting in that it will stop execution on the first\n  argument that triggers a logical false result against the original predicates.","fn"],"every?":["([pred coll])","Returns true if (pred x) is logical true for every x in coll, else\n  false.","fn"],"ex-cause":["([ex])","Returns exception cause (an Error / ExceptionInfo) if ex is an\n  ExceptionInfo.\n  Otherwise returns nil.","fn"],"ex-data":["([ex])","Returns exception data (a map) if ex is an ExceptionInfo.\n  Otherwise returns nil.","fn"],"ex-info":["([msg data] [msg data cause])","Create an instance of ExceptionInfo, an Error type that carries a\n  map of additional data.","fn"],"ex-message":["([ex])","Returns the message attached to the given Error / ExceptionInfo object.\n  For non-Errors returns nil.","fn"],"exists?":["([x])","Return true if argument exists, analogous to usage of typeof operator\n   in JavaScript.","macro"],"extend-protocol":["([p & specs])","Useful when you want to provide several implementations of the same\n  protocol all at once. Takes a single protocol and the implementation\n  of that protocol for one or more types. Expands into calls to\n  extend-type:\n\n  (extend-protocol Protocol\n    AType\n      (foo [x] ...)\n      (bar [x y] ...)\n    BType\n      (foo [x] ...)\n      (bar [x y] ...)\n    AClass\n      (foo [x] ...)\n      (bar [x y] ...)\n    nil\n      (foo [x] ...)\n      (bar [x y] ...))\n\n  expands into:\n\n  (do\n   (clojure.core/extend-type AType Protocol \n     (foo [x] ...) \n     (bar [x y] ...))\n   (clojure.core/extend-type BType Protocol \n     (foo [x] ...) \n     (bar [x y] ...))\n   (clojure.core/extend-type AClass Protocol \n     (foo [x] ...) \n     (bar [x y] ...))\n   (clojure.core/extend-type nil Protocol \n     (foo [x] ...) \n     (bar [x y] ...)))","macro"],"extend-type":["([type-sym & impls])","Extend a type to a series of protocols. Useful when you are\n  supplying the definitions explicitly inline. Propagates the\n  type as a type hint on the first argument of all fns.\n\n  type-sym may be\n\n   * default, meaning the definitions will apply for any value,\n     unless an extend-type exists for one of the more specific\n     cases below.\n   * nil, meaning the definitions will apply for the nil value.\n   * any of object, boolean, number, string, array, or function,\n     indicating the definitions will apply for values of the\n     associated base JavaScript types. Note that, for example,\n     string should be used instead of js/String.\n   * a JavaScript type not covered by the previous list, such\n     as js/RegExp.\n   * a type defined by deftype or defrecord.\n\n  (extend-type MyType\n    ICounted\n    (-count [c] ...)\n    Foo\n    (bar [x y] ...)\n    (baz ([x] ...) ([x y] ...) ...)","macro"],"false?":["([x])","Returns true if x is the value false, false otherwise.","fn"],"ffirst":["([coll])","Same as (first (first x))","fn"],"filter":["([pred] [pred coll])","Returns a lazy sequence of the items in coll for which\n  (pred item) returns logical true. pred must be free of side-effects.\n  Returns a transducer when no collection is provided.","fn"],"filterv":["([pred coll])","Returns a vector of the items in coll for which\n  (pred item) returns logical true. pred must be free of side-effects.","fn"],"find":["([coll k])","Returns the map entry for key, or nil if key not present.","fn"],"find-ns":["([ns])","Returns the namespace named by the symbol or nil if it doesn't exist.\n  Bootstrap only.","fn"],"first":["([coll])","Returns the first item in the collection. Calls seq on its\n  argument. If coll is nil, returns nil.","fn"],"flatten":["([x])","Takes any nested combination of sequential things (lists, vectors,\n  etc.) and returns their contents as a single, flat sequence.\n  (flatten nil) returns nil.","fn"],"float":["([x])",null,"fn"],"float?":["([x])","Returns true for JavaScript numbers, false otherwise.","fn"],"floats":["([x])",null,"fn"],"flush":["([])",null,"fn"],"fn":["([& sigs])","params => positional-params* , or positional-params* & next-param\n  positional-param => binding-form\n  next-param => binding-form\n  name => symbol\n\n  Defines a function","macro"],"fn?":["([f])","Return true if f is a JavaScript function or satisfies the Fn protocol.","fn"],"fnext":["([coll])","Same as (first (next x))","fn"],"fnil":["([f x] [f x y] [f x y z])","Takes a function f, and returns a function that calls f, replacing\n  a nil first argument to f with the supplied value x. Higher arity\n  versions can replace arguments in the second and third\n  positions (y, z). Note that the function f can take any number of\n  arguments, not just the one(s) being nil-patched.","fn"],"for":["([seq-exprs body-expr])","List comprehension. Takes a vector of one or more\n   binding-form/collection-expr pairs, each followed by zero or more\n   modifiers, and yields a lazy sequence of evaluations of expr.\n   Collections are iterated in a nested fashion, rightmost fastest,\n   and nested coll-exprs can refer to bindings created in prior\n   binding-forms.  Supported modifiers are: :let [binding-form expr ...],\n   :while test, :when test.\n\n  (take 100 (for [x (range 100000000) y (range 1000000) :while (< y x)]  [x y]))","macro"],"force":["([x])","If x is a Delay, returns the (possibly cached) value of its expression, else returns x","fn"],"frequencies":["([coll])","Returns a map from distinct items in coll to the number of times\n  they appear.","fn"],"gensym":["([] [prefix-string])","Returns a new symbol with a unique name. If a prefix string is\n  supplied, the name is prefix# where # is some unique number. If\n  prefix is not supplied, the prefix is 'G__'.","fn"],"get":["([o k] [o k not-found])","Returns the value mapped to key, not-found or nil if key not present\n  in associative collection, set, string, array, or ILookup instance.","fn"],"get-in":["([m ks] [m ks not-found])","Returns the value in a nested associative structure,\n  where ks is a sequence of keys. Returns nil if the key is not present,\n  or the not-found value if supplied.","fn"],"get-method":["([multifn dispatch-val])","Given a multimethod and a dispatch value, returns the dispatch fn\n  that would apply to that value, or nil if none apply and no default","fn"],"group-by":["([f coll])","Returns a map of the elements of coll keyed by the result of\n  f on each element. The value at each key will be a vector of the\n  corresponding elements, in the order they appeared in coll.","fn"],"halt-when":["([pred] [pred retf])","Returns a transducer that ends transduction when pred returns true\n  for an input. When retf is supplied it must be a fn of 2 arguments -\n  it will be passed the (completed) result so far and the input that\n  triggered the predicate, and its return value (if it does not throw\n  an exception) will be the return value of the transducer. If retf\n  is not supplied, the input that triggered the predicate will be\n  returned. If the predicate never returns true the transduction is\n  unaffected.","fn"],"hash":["([o])","Returns the hash code of its argument. Note this is the hash code\n   consistent with =.","fn"],"hash-combine":["([seed hash])",null,"fn"],"hash-map":["([& keyvals])","keyval => key val\n  Returns a new hash map with supplied mappings.","fn"],"hash-ordered-coll":["([coll])","Returns the hash code, consistent with =, for an external ordered\n   collection implementing Iterable.\n   See http://clojure.org/data_structures#hash for full algorithms.","fn"],"hash-set":["([] [& keys])","Returns a new hash set with supplied keys.  Any equal keys are\n  handled as if by repeated uses of conj.","fn"],"hash-unordered-coll":["([coll])","Returns the hash code, consistent with =, for an external unordered\n   collection implementing Iterable. For maps, the iterator should\n   return map entries whose hash is computed as\n     (hash-ordered-coll [k v]).\n   See http://clojure.org/data_structures#hash for full algorithms.","fn"],"ident?":["([x])","Return true if x is a symbol or keyword","fn"],"identical?":["([x y])","Tests if 2 arguments are the same object","fn"],"identity":["([x])","Returns its argument.","fn"],"if-let":["([bindings then] [bindings then else & oldform])","bindings => binding-form test\n\n  If test is true, evaluates then with binding-form bound to the value of \n  test, if not, yields else","macro"],"if-not":["([test then] [test then else])","Evaluates test. If logical false, evaluates and returns then expr, \n  otherwise else expr, if supplied, else nil.","macro"],"if-some":["([bindings then] [bindings then else & oldform])","bindings => binding-form test\n\n   If test is not nil, evaluates then with binding-form bound to the\n   value of test, if not, yields else","macro"],"ifn?":["([f])","Returns true if f returns true for fn? or satisfies IFn.","fn"],"inc":["([x])","Returns a number one greater than num.","fn"],"indexed?":["([x])","Returns true if coll implements nth in constant time","fn"],"infinite?":["([x])","Returns true for Infinity and -Infinity values.","fn"],"inst-ms":["([inst])","Return the number of milliseconds since January 1, 1970, 00:00:00 GMT","fn"],"inst?":["([x])","Return true if x satisfies Inst","fn"],"instance?":["([c x])","Evaluates x and tests if it is an instance of the type\n  c. Returns true or false","fn"],"int":["([x])","Coerce to int by stripping decimal places.","fn"],"int-array":["([size-or-seq] [size init-val-or-seq])","Creates an array of ints. Does not coerce array, provided for compatibility\n  with Clojure.","fn"],"int?":["([x])","Return true if x satisfies integer? or is an instance of goog.math.Integer\n   or goog.math.Long.","fn"],"integer?":["([n])","Returns true if n is a JavaScript number with no decimal part.","fn"],"interleave":["([] [c1] [c1 c2] [c1 c2 & colls])","Returns a lazy seq of the first item in each coll, then the second etc.","fn"],"interpose":["([sep] [sep coll])","Returns a lazy seq of the elements of coll separated by sep.\n  Returns a stateful transducer when no collection is provided.","fn"],"into":["([] [to] [to from] [to xform from])","Returns a new coll consisting of to-coll with all of the items of\n  from-coll conjoined. A transducer may be supplied.","fn"],"into-array":["([aseq] [type aseq])","Returns an array with components set to the values in aseq. Optional type\n  argument accepted for compatibility with Clojure.","fn"],"ints":["([x])",null,"fn"],"isa?":["([child parent] [h child parent])","Returns true if (= child parent), or child is directly or indirectly derived from\n  parent, either via a JavaScript type inheritance relationship or a\n  relationship established via derive. h must be a hierarchy obtained\n  from make-hierarchy, if not supplied defaults to the global\n  hierarchy","fn"],"iterate":["([f x])","Returns a lazy sequence of x, (f x), (f (f x)) etc. f must be free of side-effects","fn"],"iteration":["([step & {:keys [somef vf kf initk], :or {vf identity, kf identity, somef some?, initk nil}}])","Creates a seqable/reducible via repeated calls to step,\n  a function of some (continuation token) 'k'. The first call to step\n  will be passed initk, returning 'ret'. Iff (somef ret) is true,\n  (vf ret) will be included in the iteration, else iteration will\n  terminate and vf/kf will not be called. If (kf ret) is non-nil it\n  will be passed to the next step call, else iteration will terminate.\n  This can be used e.g. to consume APIs that return paginated or batched data.\n   step - (possibly impure) fn of 'k' -> 'ret'\n   :somef - fn of 'ret' -> logical true/false, default 'some?'\n   :vf - fn of 'ret' -> 'v', a value produced by the iteration, default 'identity'\n   :kf - fn of 'ret' -> 'next-k' or nil (signaling 'do not continue'), default 'identity'\n   :initk - the first value passed to step, default 'nil'\n  It is presumed that step with non-initk is unreproducible/non-idempotent.\n  If step with initk is unreproducible it is on the consumer to not consume twice.","fn"],"js->clj":["([x] [x & opts])","Recursively transforms JavaScript arrays into ClojureScript\n  vectors, and JavaScript objects into ClojureScript maps.  With\n  option ':keywordize-keys true' will convert object fields from\n  strings to keywords.","fn"],"js-delete":["([obj key])","Delete a property from a JavaScript object.\n  Returns true upon success, false otherwise.","fn"],"js-keys":["([obj])","Return the JavaScript keys for an object.","fn"],"js-obj":["([] [& keyvals])","Create JavaSript object from an even number arguments representing\n  interleaved keys and values.","fn"],"juxt":["([f] [f g] [f g h] [f g h & fs])","Takes a set of functions and returns a fn that is the juxtaposition\n  of those fns.  The returned fn takes a variable number of args, and\n  returns a vector containing the result of applying each fn to the\n  args (left-to-right).\n  ((juxt a b c) x) => [(a x) (b x) (c x)]","fn"],"keep":["([f] [f coll])","Returns a lazy sequence of the non-nil results of (f item). Note,\n  this means false return values will be included.  f must be free of\n  side-effects.  Returns a transducer when no collection is provided.","fn"],"keep-indexed":["([f] [f coll])","Returns a lazy sequence of the non-nil results of (f index item). Note,\n  this means false return values will be included.  f must be free of\n  side-effects.  Returns a stateful transducer when no collection is\n  provided.","fn"],"key":["([map-entry])","Returns the key of the map entry.","fn"],"keys":["([map])","Returns a sequence of the map's keys, in the same order as (seq map).","fn"],"keyword":["([name] [ns name])","Returns a Keyword with the given namespace and name.  Do not use :\n  in the keyword strings, it will be added automatically.","fn"],"keyword-identical?":["([x y])","Efficient test to determine that two keywords are identical.","fn"],"keyword?":["([x])","Return true if x is a Keyword","fn"],"last":["([s])","Return the last item in coll, in linear time","fn"],"lazy-cat":["([& colls])","Expands to code which yields a lazy sequence of the concatenation\n  of the supplied colls.  Each coll expr is not evaluated until it is\n  needed.\n\n  (lazy-cat xs ys zs) === (concat (lazy-seq xs) (lazy-seq ys) (lazy-seq zs))","macro"],"lazy-seq":["([& body])","Takes a body of expressions that returns an ISeq or nil, and yields\n  a ISeqable object that will invoke the body only the first time seq\n  is called, and will cache the result and return it on all subsequent\n  seq calls.","macro"],"let":["([bindings & body])","binding => binding-form init-expr\n  binding-form => name, or destructuring-form\n  destructuring-form => map-destructure-form, or seq-destructure-form\n\n  Evaluates the exprs in a lexical context in which the symbols in\n  the binding-forms are bound to their respective init-exprs or parts\n  therein.\n\n  See https://clojure.org/reference/special_forms#binding-forms for\n  more information about destructuring.","macro"],"letfn":["([fnspecs & body])","fnspec ==> (fname [params*] exprs) or (fname ([params*] exprs)+)\n\n  Takes a vector of function specs and a body, and generates a set of\n  bindings of functions to their names. All of the names are available\n  in all of the definitions of the functions, as well as the body.","macro"],"list":["([& xs])","Creates a new list containing the items.","fn"],"list*":["([args] [a args] [a b args] [a b c args] [a b c d & more])","Creates a new list containing the items prepended to the rest, the\n  last of which will be treated as a sequence.","fn"],"list?":["([x])","Returns true if x implements IList","fn"],"long":["([x])","Coerce to long by stripping decimal places. Identical to `int'.","fn"],"long-array":["([size-or-seq] [size init-val-or-seq])","Creates an array of longs. Does not coerce array, provided for compatibility\n  with Clojure.","fn"],"longs":["([x])",null,"fn"],"loop":["([bindings & body])","Evaluates the exprs in a lexical context in which the symbols in\n  the binding-forms are bound to their respective init-exprs or parts\n  therein. Acts as a recur target.","macro"],"macroexpand":["([quoted])","Repeatedly calls macroexpand-1 on form until it no longer\n  represents a macro form, then returns it.  Note neither\n  macroexpand-1 nor macroexpand expand macros in subforms.","fn"],"macroexpand-1":["([quoted])","If form represents a macro form, returns its expansion,\n  else returns form.","fn"],"make-array":["([size] [type size] [type size & more-sizes])","Construct a JavaScript array of the specified dimensions. Accepts ignored\n  type argument for compatibility with Clojure. Note that there is no efficient\n  way to allocate multi-dimensional arrays in JavaScript; as such, this function\n  will run in polynomial time when called with 3 or more arguments.","fn"],"make-hierarchy":["([])","Creates a hierarchy object for use with derive, isa? etc.","fn"],"map":["([f] [f coll] [f c1 c2] [f c1 c2 c3] [f c1 c2 c3 & colls])","Returns a lazy sequence consisting of the result of applying f to\n  the set of first items of each coll, followed by applying f to the\n  set of second items in each coll, until any one of the colls is\n  exhausted.  Any remaining items in other colls are ignored. Function\n  f should accept number-of-colls arguments. Returns a transducer when\n  no collection is provided.","fn"],"map-entry?":["([x])","Returns true if x satisfies IMapEntry","fn"],"map-indexed":["([f] [f coll])","Returns a lazy sequence consisting of the result of applying f to 0\n  and the first item of coll, followed by applying f to 1 and the second\n  item in coll, etc, until coll is exhausted. Thus function f should\n  accept 2 arguments, index and item. Returns a stateful transducer when\n  no collection is provided.","fn"],"map?":["([x])","Return true if x satisfies IMap","fn"],"mapcat":["([f] [f & colls])","Returns the result of applying concat to the result of applying map\n  to f and colls.  Thus function f should return a collection. Returns\n  a transducer when no collections are provided","fn"],"mapv":["([f coll] [f c1 c2] [f c1 c2 c3] [f c1 c2 c3 & colls])","Returns a vector consisting of the result of applying f to the\n  set of first items of each coll, followed by applying f to the set\n  of second items in each coll, until any one of the colls is\n  exhausted.  Any remaining items in other colls are ignored. Function\n  f should accept number-of-colls arguments.","fn"],"max":["([x] [x y] [x y & more])","Returns the greatest of the nums.","fn"],"max-key":["([k x] [k x y] [k x y & more])","Returns the x for which (k x), a number, is greatest.\n\n  If there are multiple such xs, the last one is returned.","fn"],"memfn":["([name & args])","Expands into code that creates a fn that expects to be passed an\n  object and any args and calls the named instance method on the\n  object passing the args. Use when you want to treat a JavaScript\n  method as a first-class fn.","macro"],"memoize":["([f])","Returns a memoized version of a referentially transparent function. The\n  memoized version of the function keeps a cache of the mapping from arguments\n  to results and, when calls with the same arguments are repeated often, has\n  higher performance at the expense of higher memory use.","fn"],"merge":["([& maps])","Returns a map that consists of the rest of the maps conj-ed onto\n  the first.  If a key occurs in more than one map, the mapping from\n  the latter (left-to-right) will be the mapping in the result.","fn"],"merge-with":["([f & maps])","Returns a map that consists of the rest of the maps conj-ed onto\n  the first.  If a key occurs in more than one map, the mapping(s)\n  from the latter (left-to-right) will be combined with the mapping in\n  the result by calling (f val-in-result val-in-latter).","fn"],"meta":["([o])","Returns the metadata of obj, returns nil if there is no metadata.","fn"],"methods":["([multifn])","Given a multimethod, returns a map of dispatch values -> dispatch fns","fn"],"min":["([x] [x y] [x y & more])","Returns the least of the nums.","fn"],"min-key":["([k x] [k x y] [k x y & more])","Returns the x for which (k x), a number, is least.\n\n  If there are multiple such xs, the last one is returned.","fn"],"mod":["([n d])","Modulus of num and div. Truncates toward negative infinity.","fn"],"munge":["([name])",null,"fn"],"name":["([x])","Returns the name String of a string, symbol or keyword.","fn"],"namespace":["([x])","Returns the namespace String of a symbol or keyword, or nil if not present.","fn"],"nat-int?":["([x])","Return true if x satisfies int? and is a natural integer value.","fn"],"neg-int?":["([x])","Return true if x satisfies int? and is negative.","fn"],"neg?":["([x])","Returns true if num is less than zero, else false","fn"],"newline":["([] [opts])","Prints a newline using *print-fn*","fn"],"next":["([coll])","Returns a seq of the items after the first. Calls seq on its\n  argument.  If there are no more items, returns nil","fn"],"nfirst":["([coll])","Same as (next (first x))","fn"],"nil?":["([x])","Returns true if x is nil, false otherwise.","fn"],"nnext":["([coll])","Same as (next (next x))","fn"],"not":["([x])","Returns true if x is logical false, false otherwise.","fn"],"not-any?":["([pred coll])","Returns false if (pred x) is logical true for any x in coll,\n  else true.","fn"],"not-empty":["([coll])","If coll is empty, returns nil, else coll","fn"],"not-every?":["([pred coll])","Returns false if (pred x) is logical true for every x in\n  coll, else true.","fn"],"not=":["([x] [x y] [x y & more])","Same as (not (= obj1 obj2))","fn"],"ns-imports":["([quoted-ns])","Returns a map of the import mappings for the namespace.","fn"],"ns-interns":["([quoted-ns])","Returns a map of the intern mappings for the namespace.","fn"],"ns-name":["([ns-obj])","Returns the name of the namespace, a Namespace object.\n  Bootstrap only.","fn"],"ns-publics":["([quoted-ns])","Returns a map of the public intern mappings for the namespace.","fn"],"ns-unmap":["([quoted-ns quoted-sym])","Removes the mappings for the symbol from the namespace.","fn"],"nth":["([coll n] [coll n not-found])","Returns the value at the index. get returns nil if index out of\n  bounds, nth throws an exception unless not-found is supplied.  nth\n  also works for strings, arrays, regex Matchers and Lists, and,\n  in O(n) time, for sequences.","fn"],"nthnext":["([coll n])","Returns the nth next of coll, (seq coll) when n is 0.","fn"],"nthrest":["([coll n])","Returns the nth rest of coll, coll when n is 0.","fn"],"number?":["([x])","Returns true if x is a JavaScript number.","fn"],"object-array":["([size-or-seq] [size init-val-or-seq])","Creates an array of objects. Does not coerce array, provided for compatibility\n  with Clojure.","fn"],"object?":["([x])","Returns true if x's constructor is Object","fn"],"odd?":["([n])","Returns true if n is odd, throws an exception if n is not an integer","fn"],"or":["([] [x] [x & next])","Evaluates exprs one at a time, from left to right. If a form\n  returns a logical true value, or returns that value and doesn't\n  evaluate any of the other expressions, otherwise it returns the\n  value of the last expression. (or) returns nil.","macro"],"parents":["([tag] [h tag])","Returns the immediate parents of tag, either via a JavaScript type\n  inheritance relationship or a relationship established via derive. h\n  must be a hierarchy obtained from make-hierarchy, if not supplied\n  defaults to the global hierarchy","fn"],"parse-boolean":["([s])","Parse strings \"true\" or \"false\" and return a boolean, or nil if invalid. Note that this explicitly\n  excludes strings with different cases, or space characters.","fn"],"parse-double":["([s])","Parse string with floating point components and return a floating point value,\n  or nil if parse fails.\n  Grammar: https://docs.oracle.com/javase/8/docs/api/java/lang/Double.html#valueOf-java.lang.String-","fn"],"parse-long":["([s])","Parse string of decimal digits with optional leading -/+ and return an\n  integer value, or nil if parse fails","fn"],"parse-uuid":["([s])","Parse a string representing a UUID and return a UUID instance,\n  or nil if parse fails.\n  Grammar: https://docs.oracle.com/javase/8/docs/api/java/util/UUID.html#toString--","fn"],"partial":["([f] [f arg1] [f arg1 arg2] [f arg1 arg2 arg3] [f arg1 arg2 arg3 & more])","Takes a function f and fewer than the normal arguments to f, and\n  returns a fn that takes a variable number of additional args. When\n  called, the returned function calls f with args + additional args.","fn"],"partition":["([n coll] [n step coll] [n step pad coll])","Returns a lazy sequence of lists of n items each, at offsets step\n  apart. If step is not supplied, defaults to n, i.e. the partitions\n  do not overlap. If a pad collection is supplied, use its elements as\n  necessary to complete last partition up to n items. In case there are\n  not enough padding elements, return a partition with less than n items.","fn"],"partition-all":["([n] [n coll] [n step coll])","Returns a lazy sequence of lists like partition, but may include\n  partitions with fewer than n items at the end.  Returns a stateful\n  transducer when no collection is provided.","fn"],"partition-by":["([f] [f coll])","Applies f to each value in coll, splitting it each time f returns a\n   new value.  Returns a lazy seq of partitions.  Returns a stateful\n   transducer when no collection is provided.","fn"],"peek":["([coll])","For a list or queue, same as first, for a vector, same as, but much\n  more efficient than, last. If the collection is empty, returns nil.","fn"],"persistent!":["([tcoll])","Returns a new, persistent version of the transient collection, in\n  constant time. The transient collection cannot be used after this\n  call, any such use will throw an exception.","fn"],"pop":["([coll])","For a list or queue, returns a new list/queue without the first\n  item, for a vector, returns a new vector without the last item.\n  Note - not the same as next/butlast.","fn"],"pop!":["([tcoll])","Removes the last item from a transient vector. If\n  the collection is empty, throws an exception. Returns tcoll","fn"],"pos-int?":["([x])","Return true if x satisfies int? and is positive.","fn"],"pos?":["([x])","Returns true if num is greater than zero, else false","fn"],"pr":["([& objs])","Prints the object(s) using string-print.  Prints the\n  object(s), separated by spaces if there is more than one.\n  By default, pr and prn print in a way that objects can be\n  read by the reader","fn"],"pr-str":["([& objs])","pr to a string, returning it. Fundamental entrypoint to IPrintWithWriter.","fn"],"prefer-method":["([multifn dispatch-val-x dispatch-val-y])","Causes the multimethod to prefer matches of dispatch-val-x over dispatch-val-y\n   when there is a conflict","fn"],"prefers":["([multifn])","Given a multimethod, returns a map of preferred value -> set of other values","fn"],"print-str":["([& objs])","print to a string, returning it","fn"],"println":["([& objs])","Same as print followed by (newline)","fn"],"prn":["([& objs])","Same as pr followed by (newline).","fn"],"prn-str":["([& objs])","Same as pr-str followed by (newline)","fn"],"qualified-ident?":["([x])","Return true if x is a symbol or keyword with a namespace","fn"],"qualified-keyword?":["([x])","Return true if x is a keyword with a namespace","fn"],"qualified-symbol?":["([x])","Return true if x is a symbol with a namespace","fn"],"quot":["([n d])","quot[ient] of dividing numerator by denominator.","fn"],"rand":["([] [n])","Returns a random floating point number between 0 (inclusive) and\n  n (default 1) (exclusive).","fn"],"rand-int":["([n])","Returns a random integer between 0 (inclusive) and n (exclusive).","fn"],"rand-nth":["([coll])","Return a random element of the (sequential) collection. Will have\n  the same performance characteristics as nth for the given\n  collection.","fn"],"random-sample":["([prob] [prob coll])","Returns items from coll with random probability of prob (0.0 -\n  1.0).  Returns a transducer when no collection is provided.","fn"],"random-uuid":["([])","Returns a pseudo-randomly generated UUID instance (i.e. type 4).","fn"],"range":["([] [end] [start end] [start end step])","Returns a lazy seq of nums from start (inclusive) to end\n   (exclusive), by step, where start defaults to 0, step to 1,\n   and end to infinity.","fn"],"re-find":["([re s])","Returns the first regex match, if any, of s to re, using\n  re.exec(s). Returns a vector, containing first the matching\n  substring, then any capturing groups if the regular expression contains\n  capturing groups.","fn"],"re-matches":["([re s])","Returns the result of (re-find re s) if re fully matches s.","fn"],"re-pattern":["([s])","Returns an instance of RegExp which has compiled the provided string.","fn"],"re-seq":["([re s])","Returns a lazy sequence of successive matches of re in s.","fn"],"read-string":["([s] [opts s])","Reads one object from the string s.\n   Returns nil when s is nil or empty.\n\n   Reads data in the edn format (subset of Clojure data):\n   http://edn-format.org\n\n   opts is a map as per cljs.tools.reader.edn/read","fn"],"realized?":["([x])","Returns true if a value has been produced for a delay or lazy sequence.","fn"],"record?":["([x])","Return true if x satisfies IRecord","fn"],"reduce":["([f coll] [f val coll])","f should be a function of 2 arguments. If val is not supplied,\n  returns the result of applying f to the first 2 items in coll, then\n  applying f to that result and the 3rd item, etc. If coll contains no\n  items, f must accept no arguments as well, and reduce returns the\n  result of calling f with no arguments.  If coll has only 1 item, it\n  is returned and f is not called.  If val is supplied, returns the\n  result of applying f to val and the first item in coll, then\n  applying f to that result and the 2nd item, etc. If coll contains no\n  items, returns val and f is not called.","fn"],"reduce-kv":["([f init coll])","Reduces an associative collection. f should be a function of 3\n  arguments. Returns the result of applying f to init, the first key\n  and the first value in coll, then applying f to that result and the\n  2nd key and value, etc. If coll contains no entries, returns init\n  and f is not called. Note that reduce-kv is supported on vectors,\n  where the keys will be the ordinals.","fn"],"reduced":["([x])","Wraps x in a way such that a reduce will terminate with the value x","fn"],"reduced?":["([r])","Returns true if x is the result of a call to reduced","fn"],"reductions":["([f coll] [f init coll])","Returns a lazy seq of the intermediate values of the reduction (as\n  per reduce) of coll by f, starting with init.","fn"],"refer-clojure":["([& args])","Refers to all the public vars of `cljs.core`, subject to\n  filters.\n  Filters can include at most one each of:\n\n  :exclude list-of-symbols\n  :rename map-of-fromsymbol-tosymbol\n\n  Filters can be used to select a subset, via exclusion, or to provide a mapping\n  to a symbol different from the var's name, in order to prevent clashes.","macro"],"reify":["([& impls])","reify creates an object implementing a protocol.\n  reify is a macro with the following structure:\n\n (reify options* specs*)\n\n  Currently there are no options.\n\n  Each spec consists of the protocol name followed by zero\n  or more method bodies:\n\n  protocol\n  (methodName [args+] body)*\n\n  Methods should be supplied for all methods of the desired\n  protocol(s). You can also define overrides for Object methods. Note that\n  the first parameter must be supplied to correspond to the target object\n  ('this' in JavaScript parlance). Note also that recur calls\n  to the method head should *not* pass the target object, it will be supplied\n  automatically and can not be substituted.\n\n  recur works to method heads The method bodies of reify are lexical\n  closures, and can refer to the surrounding local scope:\n\n  (str (let [f \"foo\"]\n       (reify Object\n         (toString [this] f))))\n  == \"foo\"\n\n  (seq (let [f \"foo\"]\n       (reify ISeqable\n         (-seq [this] (seq f)))))\n  == (\"f\" \"o\" \"o\"))\n\n  reify always implements IMeta and IWithMeta and transfers meta\n  data of the form to the created object.\n\n  (meta ^{:k :v} (reify Object (toString [this] \"foo\")))\n  == {:k :v}","macro"],"rem":["([n d])","remainder of dividing numerator by denominator.","fn"],"remove":["([pred] [pred coll])","Returns a lazy sequence of the items in coll for which\n  (pred item) returns logical false. pred must be free of side-effects.\n  Returns a transducer when no collection is provided.","fn"],"remove-all-methods":["([multifn])","Removes all of the methods of multimethod.","fn"],"remove-method":["([multifn dispatch-val])","Removes the method of multimethod associated with dispatch-value.","fn"],"remove-watch":["([iref key])","Removes a watch (set by add-watch) from a reference","fn"],"repeat":["([x] [n x])","Returns a lazy (infinite!, or length n if supplied) sequence of xs.","fn"],"repeatedly":["([f] [n f])","Takes a function of no args, presumably with side effects, and\n  returns an infinite (or length n if supplied) lazy sequence of calls\n  to it","fn"],"replace":["([smap] [smap coll])","Given a map of replacement pairs and a vector/collection, returns a\n  vector/seq with any elements = a key in smap replaced with the\n  corresponding val in smap.  Returns a transducer when no collection\n  is provided.","fn"],"require":["([& args])","Loads libs, skipping any that are already loaded. Each argument is\n  either a libspec that identifies a lib or a flag that modifies how all the identified\n  libs are loaded. Use :require in the ns macro in preference to calling this\n  directly.\n\n  Libs\n\n  A 'lib' is a named set of resources in classpath whose contents define a\n  library of ClojureScript code. Lib names are symbols and each lib is associated\n  with a ClojureScript namespace. A lib's name also locates its root directory\n  within classpath using Java's package name to classpath-relative path mapping.\n  All resources in a lib should be contained in the directory structure under its\n  root directory. All definitions a lib makes should be in its associated namespace.\n\n  'require loads a lib by loading its root resource. The root resource path\n  is derived from the lib name in the following manner:\n  Consider a lib named by the symbol 'x.y.z; it has the root directory\n  <classpath>/x/y/, and its root resource is <classpath>/x/y/z.clj. The root\n  resource should contain code to create the lib's namespace (usually by using\n  the ns macro) and load any additional lib resources.\n\n  Libspecs\n\n  A libspec is a lib name or a vector containing a lib name followed by\n  options expressed as sequential keywords and arguments.\n\n  Recognized options:\n  :as takes a symbol as its argument and makes that symbol an alias to the\n    lib's namespace in the current namespace.\n  :refer takes a list of symbols to refer from the namespace.\n  :refer-macros takes a list of macro symbols to refer from the namespace.\n  :include-macros true causes macros from the namespace to be required.\n  :rename specifies a map from referred var names to different\n    symbols (and can be used to prevent clashes)\n\n\n  Flags\n\n  A flag is a keyword.\n  Recognized flags: :reload, :reload-all, :verbose\n  :reload forces loading of all the identified libs even if they are\n    already loaded\n  :reload-all implies :reload and also forces loading of all libs that the\n    identified libs directly or indirectly load via require or use\n  :verbose triggers printing information about each load, alias, and refer\n\n  Example:\n\n  The following would load the library clojure.string :as string.\n\n  (require '[clojure.string :as string])","fn"],"reset!":["([a new-value])","Sets the value of atom to newval without regard for the\n  current value. Returns new-value.","fn"],"reset-meta!":["([iref m])","Atomically resets the metadata for an atom","fn"],"resolve":["([quoted-sym])","Returns the var to which a symbol will be resolved in the namespace else nil.","fn"],"rest":["([coll])","Returns a possibly empty seq of the items after the first. Calls seq on its\n  argument.","fn"],"reverse":["([coll])","Returns a seq of the items in coll in reverse order. Not lazy.","fn"],"reversible?":["([coll])","Returns true if coll satisfies? IReversible.","fn"],"rseq":["([rev])","Returns, in constant time, a seq of the items in rev (which\n  can be a vector or sorted-map), in reverse order. If rev is empty returns nil","fn"],"rsubseq":["([sc test key] [sc start-test start-key end-test end-key])","sc must be a sorted collection, test(s) one of <, <=, > or\n  >=. Returns a reverse seq of those entries with keys ek for\n  which (test (.. sc comparator (compare ek key)) 0) is true","fn"],"run!":["([proc coll])","Runs the supplied procedure (via reduce), for purposes of side\n  effects, on successive items in the collection. Returns nil","fn"],"second":["([coll])","Same as (first (next x))","fn"],"select-keys":["([map keyseq])","Returns a map containing only those entries in map whose key is in keys","fn"],"seq":["([coll])","Returns a seq on the collection. If the collection is\n  empty, returns nil.  (seq nil) returns nil. seq also works on\n  Strings.","fn"],"seq-to-map-for-destructuring":["([s])","Builds a map from a seq as described in\n  https://clojure.org/reference/special_forms#keyword-arguments","fn"],"seq?":["([s])","Return true if s satisfies ISeq","fn"],"seqable?":["([s])","Return true if the seq function is supported for s","fn"],"sequence":["([coll] [xform coll] [xform coll & colls])","Coerces coll to a (possibly empty) sequence, if it is not already\n  one. Will not force a lazy seq. (sequence nil) yields (), When a\n  transducer is supplied, returns a lazy sequence of applications of\n  the transform to the items in coll(s), i.e. to the set of first\n  items of each coll, followed by the set of second\n  items in each coll, until any one of the colls is exhausted.  Any\n  remaining items in other colls are ignored. The transform should accept\n  number-of-colls arguments","fn"],"sequential?":["([x])","Returns true if coll satisfies ISequential","fn"],"set":["([coll])","Returns a set of the distinct elements of coll.","fn"],"set?":["([x])","Returns true if x satisfies ISet","fn"],"short":["([x])",null,"fn"],"shorts":["([x])",null,"fn"],"shuffle":["([coll])","Return a random permutation of coll","fn"],"simple-ident?":["([x])","Return true if x is a symbol or keyword without a namespace","fn"],"simple-keyword?":["([x])","Return true if x is a keyword without a namespace","fn"],"simple-symbol?":["([x])","Return true if x is a symbol without a namespace","fn"],"some":["([pred coll])","Returns the first logical true value of (pred x) for any x in coll,\n  else nil.  One common idiom is to use a set as pred, for example\n  this will return :fred if :fred is in the sequence, otherwise nil:\n  (some #{:fred} coll)","fn"],"some->":["([expr & forms])","When expr is not nil, threads it into the first form (via ->),\n  and when that result is not nil, through the next etc","macro"],"some->>":["([expr & forms])","When expr is not nil, threads it into the first form (via ->>),\n  and when that result is not nil, through the next etc","macro"],"some-fn":["([p] [p1 p2] [p1 p2 p3] [p1 p2 p3 & ps])","Takes a set of predicates and returns a function f that returns the first logical true value\n  returned by one of its composing predicates against any of its arguments, else it returns\n  logical false. Note that f is short-circuiting in that it will stop execution on the first\n  argument that triggers a logical true result against the original predicates.","fn"],"some?":["([x])","Returns true if x is not nil, false otherwise.","fn"],"sort":["([coll] [comp coll])","Returns a sorted sequence of the items in coll. Comp can be\n   boolean-valued comparison function, or a -/0/+ valued comparator.\n   Comp defaults to compare.","fn"],"sort-by":["([keyfn coll] [keyfn comp coll])","Returns a sorted sequence of the items in coll, where the sort\n   order is determined by comparing (keyfn item).  Comp can be\n   boolean-valued comparison function, or a -/0/+ valued comparator.\n   Comp defaults to compare.","fn"],"sorted-map":["([& keyvals])","keyval => key val\n  Returns a new sorted map with supplied mappings.","fn"],"sorted-map-by":["([comparator & keyvals])","keyval => key val\n  Returns a new sorted map with supplied mappings, using the supplied comparator.","fn"],"sorted-set":["([& keys])","Returns a new sorted set with supplied keys.","fn"],"sorted-set-by":["([comparator & keys])","Returns a new sorted set with supplied keys, using the supplied comparator.","fn"],"sorted?":["([x])","Returns true if coll satisfies ISorted","fn"],"special-symbol?":["([x])","Returns true if x names a special form","fn"],"split-at":["([n coll])","Returns a vector of [(take n coll) (drop n coll)]","fn"],"split-with":["([pred coll])","Returns a vector of [(take-while pred coll) (drop-while pred coll)]","fn"],"str":["([] [x] [x & ys])","With no args, returns the empty string. With one arg x, returns\n  x.toString().  (str nil) returns the empty string. With more than\n  one arg, returns the concatenation of the str values of the args.","fn"],"string?":["([x])","Returns true if x is a JavaScript string.","fn"],"subs":["([s start] [s start end])","Returns the substring of s beginning at start inclusive, and ending\n  at end (defaults to length of string), exclusive.","fn"],"subseq":["([sc test key] [sc start-test start-key end-test end-key])","sc must be a sorted collection, test(s) one of <, <=, > or\n  >=. Returns a seq of those entries with keys ek for\n  which (test (.. sc comparator (compare ek key)) 0) is true","fn"],"subvec":["([v start] [v start end])","Returns a persistent vector of the items in vector from\n  start (inclusive) to end (exclusive).  If end is not supplied,\n  defaults to (count vector). This operation is O(1) and very fast, as\n  the resulting vector shares structure with the original and no\n  trimming is done.","fn"],"swap!":["([a f] [a f x] [a f x y] [a f x y & more])","Atomically swaps the value of atom to be:\n  (apply f current-value-of-atom args). Note that f may be called\n  multiple times, and thus should be free of side effects.  Returns\n  the value that was swapped in.","fn"],"symbol":["([name] [ns name])","Returns a Symbol with the given namespace and name. Arity-1 works\n  on strings, keywords, and vars.","fn"],"symbol?":["([x])","Return true if x is a Symbol","fn"],"system-time":["([])","Returns highest resolution time offered by host in milliseconds.","fn"],"tagged-literal":["([tag form])","Construct a data representation of a tagged literal from a\n  tag symbol and a form.","fn"],"tagged-literal?":["([value])","Return true if the value is the data representation of a tagged literal","fn"],"take":["([n] [n coll])","Returns a lazy sequence of the first n items in coll, or all items if\n  there are fewer than n.  Returns a stateful transducer when\n  no collection is provided.","fn"],"take-last":["([n coll])","Returns a seq of the last n items in coll.  Depending on the type\n  of coll may be no better than linear time.  For vectors, see also subvec.","fn"],"take-nth":["([n] [n coll])","Returns a lazy seq of every nth item in coll.  Returns a stateful\n  transducer when no collection is provided.","fn"],"take-while":["([pred] [pred coll])","Returns a lazy sequence of successive items from coll while\n  (pred item) returns logical true. pred must be free of side-effects.\n  Returns a transducer when no collection is provided.","fn"],"test":["([v])","test [v] finds fn at key :test in var metadata and calls it,\n  presuming failure will throw exception","fn"],"time":["([expr])","Evaluates expr and prints the time it took. Returns the value of expr.","macro"],"to-array":["([coll])","Returns an array containing the contents of coll.","fn"],"to-array-2d":["([coll])","Returns a (potentially-ragged) 2-dimensional array\n  containing the contents of coll.","fn"],"trampoline":["([f] [f & args])","trampoline can be used to convert algorithms requiring mutual\n  recursion without stack consumption. Calls f with supplied args, if\n  any. If f returns a fn, calls that fn with no arguments, and\n  continues to repeat, until the return value is not a fn, then\n  returns that non-fn value. Note that if you want to return a fn as a\n  final value, you must wrap it in some data structure and unpack it\n  after trampoline returns.","fn"],"transduce":["([xform f coll] [xform f init coll])","reduce with a transformation of f (xf). If init is not\n  supplied, (f) will be called to produce it. f should be a reducing\n  step function that accepts both 1 and 2 arguments, if it accepts\n  only 2 you can add the arity-1 with 'completing'. Returns the result\n  of applying (the transformed) xf to init and the first item in coll,\n  then applying xf to that result and the 2nd item, etc. If coll\n  contains no items, returns init and f is not called. Note that\n  certain transforms may inject or skip items.","fn"],"transient":["([coll])","Returns a new, transient version of the collection, in constant time.","fn"],"tree-seq":["([branch? children root])","Returns a lazy sequence of the nodes in a tree, via a depth-first walk.\n  branch? must be a fn of one arg that returns true if passed a node\n  that can have children (but may not).  children must be a fn of one\n  arg that returns a sequence of the children. Will only be called on\n  nodes for which branch? returns true. Root is the root node of the\n  tree.","fn"],"true?":["([x])","Returns true if x is the value true, false otherwise.","fn"],"type":["([x])","Return x's constructor.","fn"],"unchecked-add":["([] [x] [x y] [x y & more])","Returns the sum of nums. (+) returns 0.","fn"],"unchecked-add-int":["([] [x] [x y] [x y & more])","Returns the sum of nums. (+) returns 0.","fn"],"unchecked-byte":["([x])",null,"fn"],"unchecked-char":["([x])",null,"fn"],"unchecked-dec":["([x])","Returns a number one less than x, an int.","fn"],"unchecked-dec-int":["([x])","Returns a number one less than x, an int.","fn"],"unchecked-divide-int":["([x] [x y] [x y & more])","If no denominators are supplied, returns 1/numerator,\n  else returns numerator divided by all of the denominators.","fn"],"unchecked-double":["([x])",null,"fn"],"unchecked-float":["([x])",null,"fn"],"unchecked-inc":["([x])",null,"fn"],"unchecked-inc-int":["([x])",null,"fn"],"unchecked-int":["([x])","Coerce to int by stripping decimal places.","fn"],"unchecked-long":["([x])","Coerce to long by stripping decimal places. Identical to `int'.","fn"],"unchecked-multiply":["([] [x] [x y] [x y & more])","Returns the product of nums. (*) returns 1.","fn"],"unchecked-multiply-int":["([] [x] [x y] [x y & more])","Returns the product of nums. (*) returns 1.","fn"],"unchecked-negate":["([x])",null,"fn"],"unchecked-negate-int":["([x])",null,"fn"],"unchecked-remainder-int":["([x n])",null,"fn"],"unchecked-short":["([x])",null,"fn"],"unchecked-subtract":["([x] [x y] [x y & more])","If no ys are supplied, returns the negation of x, else subtracts\n  the ys from x and returns the result.","fn"],"unchecked-subtract-int":["([x] [x y] [x y & more])","If no ys are supplied, returns the negation of x, else subtracts\n  the ys from x and returns the result.","fn"],"undefined?":["([x])","Returns true if x identical to the JavaScript undefined value.","fn"],"underive":["([tag parent] [h tag parent])","Removes a parent/child relationship between parent and\n  tag. h must be a hierarchy obtained from make-hierarchy, if not\n  supplied defaults to, and modifies, the global hierarchy.","fn"],"unreduced":["([x])","If x is reduced?, returns (deref x), else returns x","fn"],"unsigned-bit-shift-right":["([x n])","Bitwise shift right with zero fill","fn"],"update":["([m k f] [m k f x] [m k f x y] [m k f x y z] [m k f x y z & more])","'Updates' a value in an associative structure, where k is a\n  key and f is a function that will take the old value\n  and any supplied args and return the new value, and returns a new\n  structure.  If the key does not exist, nil is passed as the old value.","fn"],"update-in":["([m [k & ks] f] [m [k & ks] f a] [m [k & ks] f a b] [m [k & ks] f a b c] [m [k & ks] f a b c & args])","'Updates' a value in a nested associative structure, where ks is a\n  sequence of keys and f is a function that will take the old value\n  and any supplied args and return the new value, and returns a new\n  nested structure.  If any levels do not exist, hash-maps will be\n  created.","fn"],"update-keys":["([m f])","m f => {(f k) v ...}\n  Given a map m and a function f of 1-argument, returns a new map whose\n  keys are the result of applying f to the keys of m, mapped to the\n  corresponding values of m.\n  f must return a unique key for each key of m, else the behavior is undefined.","fn"],"update-vals":["([m f])","m f => {k (f v) ...}\n  Given a map m and a function f of 1-argument, returns a new map where the keys of m\n  are mapped to result of applying f to the corresponding values of m.","fn"],"uri?":["([x])","Returns true x is a goog.Uri instance.","fn"],"use":["([& args])","Like require, but referring vars specified by the mandatory\n  :only option.\n\n  Example:\n\n  The following would load the library clojure.set while referring\n  the intersection var.\n\n  (use '[clojure.set :only [intersection]])","fn"],"uuid?":["([x])","Return true if x is a UUID.","fn"],"val":["([map-entry])","Returns the value in the map entry.","fn"],"vals":["([map])","Returns a sequence of the map's values, in the same order as (seq map).","fn"],"var?":["([v])","Returns true if v is of type cljs.core.Var","fn"],"vary-meta":["([obj f] [obj f a] [obj f a b] [obj f a b c] [obj f a b c d] [obj f a b c d & args])","Returns an object of the same type and value as obj, with\n  (apply f (meta obj) args) as its metadata.","fn"],"vec":["([coll])","Creates a new vector containing the contents of coll. JavaScript arrays\n  will be aliased and should not be modified.","fn"],"vector":["([& args])","Creates a new vector containing the args.","fn"],"vector?":["([x])","Return true if x satisfies IVector","fn"],"volatile!":["([val])","Creates and returns a Volatile with an initial value of val.","fn"],"volatile?":["([x])","Returns true if x is a volatile.","fn"],"vreset!":["([vol newval])","Sets the value of volatile to newval without regard for the\n   current value. Returns newval.","fn"],"vswap!":["([vol f & args])","Non-atomically swaps the value of the volatile as if:\n   (apply f current-value-of-vol args). Returns the value that\n   was swapped in.","macro"],"when":["([test & body])","Evaluates test. If logical true, evaluates body in an implicit do.","macro"],"when-first":["([bindings & body])","bindings => x xs\n\n  Roughly the same as (when (seq xs) (let [x (first xs)] body)) but xs is evaluated only once","macro"],"when-let":["([bindings & body])","bindings => binding-form test\n\n  When test is true, evaluates body with binding-form bound to the value of test","macro"],"when-not":["([test & body])","Evaluates test. If logical false, evaluates body in an implicit do.","macro"],"when-some":["([bindings & body])","bindings => binding-form test\n\n   When test is not nil, evaluates body with binding-form bound to the\n   value of test","macro"],"while":["([test & body])","Repeatedly executes body while test expression is true. Presumes\n  some side-effect will cause test to become false/nil. Returns nil","macro"],"with-meta":["([o meta])","Returns an object of the same type and value as obj, with\n  map m as its metadata.","fn"],"with-out-str":["([& body])","Evaluates exprs in a context in which *print-fn* is bound to .append\n  on a fresh StringBuffer.  Returns the string created by any nested\n  printing calls.","macro"],"with-redefs":["([bindings & body])","binding => var-symbol temp-value-expr\n\n  Temporarily redefines vars while executing the body.  The\n  temp-value-exprs will be evaluated and each resulting value will\n  replace in parallel the root value of its var.  After the body is\n  executed, the root values of all the vars will be set back to their\n  old values. Useful for mocking out functions during testing.","macro"],"zero?":["([x])","Returns true if num is zero, else false","fn"],"zipmap":["([keys vals])","Returns a map with the keys mapped to the corresponding vals.","fn"]},"clojure.string":{"blank?":["([s])","True if s is nil, empty, or contains only whitespace.","fn"],"capitalize":["([s])","Converts first character of the string to upper-case, all other\n  characters to lower-case.","fn"],"ends-with?":["([s substr])","True if s ends with substr.","fn"],"escape":["([s cmap])","Return a new string, using cmap to escape each character ch\n   from s as follows:\n\n   If (cmap ch) is nil, append ch to the new string.\n   If (cmap ch) is non-nil, append (str (cmap ch)) instead.","fn"],"includes?":["([s substr])","True if s includes substr.","fn"],"index-of":["([s value] [s value from-index])","Return index of value (string or char) in s, optionally searching\n  forward from from-index or nil if not found.","fn"],"join":["([coll] [separator coll])","Returns a string of all elements in coll, as returned by (seq coll),\n  separated by an optional separator.","fn"],"last-index-of":["([s value] [s value from-index])","Return last index of value (string or char) in s, optionally\n  searching backward from from-index or nil if not found.","fn"],"lower-case":["([s])","Converts string to all lower-case.","fn"],"replace":["([s match replacement])","Replaces all instance of match with replacement in s.\n\n   match/replacement can be:\n\n   string / string\n   pattern / (string or function of match).\n\n   See also replace-first.\n\n   The replacement is literal (i.e. none of its characters are treated\n   specially) for all cases above except pattern / string.\n\n   For pattern / string, $1, $2, etc. in the replacement string are\n   substituted with the string that matched the corresponding\n   parenthesized group in the pattern.\n\n   Example:\n   (clojure.string/replace \"Almost Pig Latin\" #\"\\b(\\w)(\\w+)\\b\" \"$2$1ay\")\n   -> \"lmostAay igPay atinLay\"","fn"],"replace-first":["([s match replacement])","Replaces the first instance of match with replacement in s.\n\n   match/replacement can be:\n\n   string / string\n   pattern / (string or function of match).\n\n   See also replace.\n\n   The replacement is literal (i.e. none of its characters are treated\n   specially) for all cases above except pattern / string.\n\n   For pattern / string, $1, $2, etc. in the replacement string are\n   substituted with the string that matched the corresponding\n   parenthesized group in the pattern.\n\n   Example:\n   (clojure.string/replace-first \"swap first two words\"\n                                 #\"(\\w+)(\\s+)(\\w+)\" \"$3$2$1\")\n   -> \"first swap two words\"","fn"],"reverse":["([s])","Returns s with its characters reversed.","fn"],"split":["([s re] [s re limit])","Splits string on a regular expression. Optional argument limit is\n  the maximum number of parts. Not lazy. Returns vector of the parts.\n  Trailing empty strings are not returned - pass limit of -1 to return all.","fn"],"split-lines":["([s])","Splits s on \\n or \\r\\n. Trailing empty lines are not returned.","fn"],"starts-with?":["([s substr])","True if s starts with substr.","fn"],"trim":["([s])","Removes whitespace from both ends of string.","fn"],"trim-newline":["([s])","Removes all trailing newline \\n or return \\r characters from\n  string.  Similar to Perl's chomp.","fn"],"triml":["([s])","Removes whitespace from the left side of string.","fn"],"trimr":["([s])","Removes whitespace from the right side of string.","fn"],"upper-case":["([s])","Converts string to all upper-case.","fn"]},"clojure.set":{"difference":["([s1] [s1 s2] [s1 s2 & sets])","Return a set that is the first set without elements of the remaining sets","fn"],"index":["([xrel ks])","Returns a map of the distinct values of ks in the xrel mapped to a\n  set of the maps in xrel with the corresponding values of ks.","fn"],"intersection":["([s1] [s1 s2] [s1 s2 & sets])","Return a set that is the intersection of the input sets","fn"],"join":["([xrel yrel] [xrel yrel km])","When passed 2 rels, returns the rel corresponding to the natural\n  join. When passed an additional keymap, joins on the corresponding\n  keys.","fn"],"map-invert":["([m])","Returns the map with the vals mapped to the keys.","fn"],"project":["([xrel ks])","Returns a rel of the elements of xrel with only the keys in ks","fn"],"rename":["([xrel kmap])","Returns a rel of the maps in xrel with the keys in kmap renamed to the vals in kmap","fn"],"rename-keys":["([map kmap])","Returns the map with the keys in kmap renamed to the vals in kmap","fn"],"select":["([pred xset])","Returns a set of the elements for which pred is true","fn"],"subset?":["([set1 set2])","Is set1 a subset of set2?","fn"],"superset?":["([set1 set2])","Is set1 a superset of set2?","fn"],"union":["([] [s1] [s1 s2] [s1 s2 & sets])","Return a set that is the union of the input sets","fn"]},"clojure.walk":{"keywordize-keys":["([m])","Recursively transforms all map keys from strings to keywords.","fn"],"postwalk":["([f form])","Performs a depth-first, post-order traversal of form.  Calls f on\n  each sub-form, uses f's return value in place of the original.\n  Recognizes all Clojure data structures. Consumes seqs as with doall.","fn"],"postwalk-replace":["([smap form])","Recursively transforms form by replacing keys in smap with their\n  values.  Like clojure/replace but works on any data structure.  Does\n  replacement at the leaves of the tree first.","fn"],"prewalk":["([f form])","Like postwalk, but does pre-order traversal.","fn"],"prewalk-replace":["([smap form])","Recursively transforms form by replacing keys in smap with their\n  values.  Like clojure/replace but works on any data structure.  Does\n  replacement at the root of the tree first.","fn"],"stringify-keys":["([m])","Recursively transforms all map keys from keywords to strings.","fn"],"walk":["([inner outer form])","Traverses form, an arbitrary data structure.  inner and outer are\n  functions.  Applies inner to each element of form, building up a\n  data structure of the same type, then applies outer to the result.\n  Recognizes all Clojure data structures. Consumes seqs as with doall.","fn"]},"clojure.edn":{"read":["([reader] [opts reader] [reader eof-error? eof opts])","Reads the first object from an cljs.tools.reader.reader-types/IPushbackReader.\n   Returns the object read. If EOF, throws if eof-error? is true otherwise returns eof.\n   If no reader is provided, *in* will be used.\n\n   Reads data in the edn format (subset of Clojure data):\n   http://edn-format.org\n\n   cljs.tools.reader.edn/read doesn't depend on dynamic Vars, all configuration\n   is done by passing an opt map.\n\n   opts is a map that can include the following keys:\n   :eof - value to return on end-of-file. When not supplied, eof throws an exception.\n   :readers  - a map of tag symbols to data-reader functions to be considered before default-data-readers.\n              When not supplied, only the default-data-readers will be used.\n   :default - A function of two args, that will, if present and no reader is found for a tag,\n              be called with the tag and the value.","fn"],"read-string":["([s] [opts s])","Reads one object from the string s.\n   Returns nil when s is nil or empty.\n\n   Reads data in the edn format (subset of Clojure data):\n   http://edn-format.org\n\n   opts is a map as per cljs.tools.reader.edn/read","fn"]},"__special":{"if":["(if test then else?)","Evaluates test. If not nil or false, evaluates and yields then, otherwise, evaluates and yields else. If else is not supplied it defaults to nil."],"do":["(do exprs*)","Evaluates the expressions in order and returns the value of the last. If no expressions are supplied, returns nil."],"quote":["(quote form)","Yields the unevaluated form."],"var":["(var symbol)","The symbol must resolve to a var, and the Var object itself (not its value) is returned."],"recur":["(recur exprs*)","Evaluates the exprs in order, then, in parallel, rebinds the bindings of the recursion point to the values of the exprs. Must appear in tail position."],"throw":["(throw expr)","The expr is evaluated and thrown."],"try":["(try expr* catch-clause* finally-clause?)","The exprs are evaluated and, if no exceptions occur, the value of the last is returned. If an exception occurs and catch clauses are provided, its expressions are evaluated in a context in which the named binding is bound to the thrown exception."],"def":["(def symbol doc-string? init?)","Creates and interns a global var with the name of symbol, with the value of init if supplied."],"set!":["(set! var-symbol expr)","Assignment special form: sets the value of the var or js field."],"new":["(new Classname args*)","Instantiates a constructor. The form (Classname. args*) is sugar for this."]}};
